test("supervisor lease honors live foreign owners and stale reclaim; workers cannot acquire", async () => {
	const cwd = makeProject();
	const originalRole = process.env.PI_WORKFLOW_ROLE;
	try {
		process.env.PI_WORKFLOW_ROLE = "supervisor";
		const runId = "workflow_unit_lease";
		assert.equal(await acquireSupervisorLease(cwd, runId), true);
		assert.equal(workflowProcessRoleForTests(), "supervisor");

		const ownLease = JSON.parse(
			readFileSync(supervisorLeasePath(cwd, runId), "utf8"),
		);
		assert.equal(ownLease.ownerId, workflowSupervisorOwnerIdForTests());
		await writeJsonAtomic(supervisorLeasePath(cwd, runId), {
			...ownLease,
			heartbeatAt: "2000-01-01T00:00:00.000Z",
		});
		assert.equal(await heartbeatSupervisorLease(cwd, runId), true);
		const heartbeaten = JSON.parse(
			readFileSync(supervisorLeasePath(cwd, runId), "utf8"),
		);
		assert.equal(heartbeaten.ownerId, workflowSupervisorOwnerIdForTests());
		assert.notEqual(heartbeaten.heartbeatAt, "2000-01-01T00:00:00.000Z");

		const foreignLiveRunId = "workflow_unit_foreign_live";
		await writeJsonAtomic(supervisorLeasePath(cwd, foreignLiveRunId), {
			schemaVersion: 1,
			ownerId: "foreign-live",
			pid: process.pid,
			role: "supervisor",
			startedAt: new Date().toISOString(),
			heartbeatAt: new Date().toISOString(),
		});
		assert.equal(await acquireSupervisorLease(cwd, foreignLiveRunId), false);

		const foreignStaleRunId = "workflow_unit_foreign_stale";
		await writeJsonAtomic(supervisorLeasePath(cwd, foreignStaleRunId), {
			schemaVersion: 1,
			ownerId: "foreign-stale",
			pid: 99999999,
			role: "supervisor",
			startedAt: "2000-01-01T00:00:00.000Z",
			heartbeatAt: "2000-01-01T00:00:00.000Z",
		});
		assert.equal(await acquireSupervisorLease(cwd, foreignStaleRunId), true);

		process.env.PI_WORKFLOW_ROLE = "worker";
		assert.equal(
			await acquireSupervisorLease(cwd, "workflow_unit_worker"),
			false,
		);
	} finally {
		if (originalRole === undefined) delete process.env.PI_WORKFLOW_ROLE;
		else process.env.PI_WORKFLOW_ROLE = originalRole;
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("run lease stale reclaim admits exactly one concurrent owner", async () => {
	const cwd = makeProject();
	try {
		const runId = "workflow_unit_lock_reclaim_race";
		writeSupervisorLock(cwd, runId, {
			createdAt: "2000-01-01T00:00:00.000Z",
			mtime: new Date(Date.now() - 60_000),
		});

		const results = await Promise.all([
			withRunLease(cwd, runId, async () => {
				await sleep(100);
				return "first";
			}),
			withRunLease(cwd, runId, async () => {
				await sleep(100);
				return "second";
			}),
		]);

		assert.equal(results.filter(Boolean).length, 1);
		assert.equal(results.filter((value) => value === undefined).length, 1);
	} finally {
		setRunLeaseTestHooksForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("run lease restore fails clearly if another owner appears during reclaim restore", async () => {
	const cwd = makeProject();
	let thirdPartyFd;
	try {
		const runId = "workflow_unit_lock_restore_race";
		const lockFile = writeSupervisorLock(cwd, runId, {
			createdAt: "2000-01-01T00:00:00.000Z",
			mtime: new Date(Date.now() - 60_000),
		});
		setRunLeaseTestHooksForTests({
			onAfterReclaimRename({ reclaimFile }) {
				writeFileSync(
					reclaimFile,
					`fresh-owner\n${process.pid}\n${new Date().toISOString()}\n`,
					"utf8",
				);
			},
			onBeforeRestoreReclaimFile({ lockFile: path }) {
				thirdPartyFd = openSync(path, "wx");
				writeFileSync(
					thirdPartyFd,
					`third-party\n${process.pid}\n${new Date().toISOString()}\n`,
					"utf8",
				);
				closeSync(thirdPartyFd);
				thirdPartyFd = undefined;
			},
		});

		await assert.rejects(
			() => withRunLease(cwd, runId, async () => "unreachable"),
			/Could not restore reclaimed lock/,
		);
		assert.match(readFileSync(lockFile, "utf8"), /^third-party\n/);
	} finally {
		if (thirdPartyFd !== undefined) closeSync(thirdPartyFd);
		setRunLeaseTestHooksForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

