		const initialIndexUpdatedAt = readWorkflowIndexFile(cwd).updatedAt;
		run.tasks[0].lastMessage = "nonterminal two";
		await writeRunRecord(cwd, run);
		await sleep(50);
		assert.equal(existsSync(join(cwd, ".pi", "workflows", "index.json")), true);
