test("notifyUnfinishedRuns reports recent failed root runs with resume hint", async () => {
	const cwd = makeProject();
	try {
		const nowMs = Date.parse("2026-06-12T12:00:00.000Z");
		const indexDir = join(cwd, ".pi", "workflows");
		mkdirSync(indexDir, { recursive: true });
		const summary = {
			pending: 0,
			running: 0,
			blocked: 0,
			completed: 1,
			failed: 1,
			skipped: 3,
			interrupted: 0,
			total: 5,
		};
		writeFileSync(
			join(indexDir, "index.json"),
			JSON.stringify({
				schemaVersion: 1,
				updatedAt: "2026-06-12T11:00:00.000Z",
				runs: [
					{
						runId: "workflow_recent",
						name: "deep-research",
						type: "artifact-graph",
						status: "failed",
						taskSummary: summary,
						createdAt: "2026-06-11T00:00:00.000Z",
						updatedAt: "2026-06-11T00:00:00.000Z",
						runJson: "x",
						tasks: [],
					},
					{
						runId: "workflow_old",
						name: "stale",
						type: "artifact-graph",
						status: "failed",
						taskSummary: summary,
						createdAt: "2026-05-01T00:00:00.000Z",
						updatedAt: "2026-05-01T00:00:00.000Z",
						runJson: "x",
						tasks: [],
					},
					{
						runId: "workflow_child",
						name: "loop-child",
						type: "artifact-graph",
						status: "failed",
						parentRunId: "workflow_recent",
						taskSummary: summary,
						createdAt: "2026-06-11T00:00:00.000Z",
						updatedAt: "2026-06-11T00:00:00.000Z",
						runJson: "x",
						tasks: [],
					},
					{
						runId: "workflow_done",
						name: "ok",
						type: "artifact-graph",
						status: "completed",
						taskSummary: summary,
						createdAt: "2026-06-11T00:00:00.000Z",
						updatedAt: "2026-06-11T00:00:00.000Z",
						runJson: "x",
						tasks: [],
					},
				],
			}),
		);
		writeUnfinishedNoticeIndex(
			cwd,
			JSON.parse(readFileSync(join(indexDir, "index.json"))).runs,
		);

		const notices = [];
		await notifyUnfinishedRuns(
			cwd,
			(message, type) => notices.push({ message, type }),
			nowMs,
		);
		assert.equal(notices.length, 1);
		assert.equal(notices[0].type, "warning");
		assert.match(notices[0].message, /deep-research workflow_recent: failed/);
		assert.match(notices[0].message, /\/workflow resume workflow_recent/);
		assert.doesNotMatch(
			notices[0].message,
			/workflow_old|workflow_child|workflow_done/,
		);

		const duplicate = [];
		await notifyUnfinishedRuns(
			cwd,
			(message, type) => duplicate.push({ message, type }),
			nowMs + 60_000,
		);
		assert.equal(duplicate.length, 0);

		const later = [];
		await notifyUnfinishedRuns(
			cwd,
			(message, type) => later.push({ message, type }),
			nowMs + 7 * 60 * 60 * 1000,
		);
		assert.equal(later.length, 1);

		const silent = [];
		await notifyUnfinishedRuns(
			join(cwd, "no-such"),
			(message) => silent.push(message),
			nowMs,
		);
		assert.equal(silent.length, 0);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

