test("launch-bootstrap provenance is deterministic, attempt-scoped, and bounded on mismatch", async () => {
	const cwd = makeProject();
	try {
		const fixture = makeSubagentLaunchFixture(cwd, "bootstrap");
		const first = await createLaunchBootstrapProvenance(
			cwd,
			fixture.run,
			fixture.task,
			fixture.compiledTask,
			"pi-subagent/headless",
		);
		const repeat = await createLaunchBootstrapProvenance(
			cwd,
			fixture.run,
			fixture.task,
			fixture.compiledTask,
			"pi-subagent/headless",
		);
		assert.deepEqual(
			canonicalLaunchBootstrapBytes(first),
			canonicalLaunchBootstrapBytes(repeat),
		);
		assert.equal(first.artifacts, undefined);
		assert.equal(
			canonicalLaunchBootstrapBytes({ z: 1, a: 2, ä: 3 }).toString("utf8"),
			'{"a":2,"z":1,"ä":3}',
		);
		const orderOnly = structuredClone(fixture);
		orderOnly.compiledTask.contextDependsOn = undefined;
		orderOnly.compiledTask.dependsOn = ["order-only"];
		assert.deepEqual(
			(
				await createLaunchBootstrapProvenance(
					cwd,
					orderOnly.run,
					orderOnly.task,
					orderOnly.compiledTask,
					"pi-subagent/headless",
				)
			).sourceDependencies.contextDependsOn,
			[],
		);
		recordLaunchBootstrapProvenance(fixture.task, first);
		recordLaunchBootstrapProvenance(fixture.task, repeat);
		assert.equal(fixture.task.launchBootstrap.records.length, 1);
		const malformed = structuredClone(first);
		malformed.identitySha256 = "0".repeat(64);
		assert.throws(
			() =>
				recordLaunchBootstrapProvenance(
					structuredClone(orderOnly.task),
					malformed,
				),
			/launch-bootstrap provenance is malformed/,
		);
		const duplicateHistoryTask = structuredClone(orderOnly.task);
		duplicateHistoryTask.launchBootstrap = {
			version: 1,
			records: [structuredClone(first), structuredClone(first)],
		};
		assert.throws(
			() => recordLaunchBootstrapProvenance(duplicateHistoryTask, first),
			/launch-bootstrap provenance is malformed/,
		);
		const incompleteIdentity = {
			schema: "pi-workflow-launch-bootstrap-provenance-v1",
			attempt: {
				key: "launch-retry:0;output-retry:0;resume:0;session:none",
				launchRetry: 0,
				outputRetry: 0,
				resume: 0,
			},
		};
		const incompleteHistoryTask = structuredClone(orderOnly.task);
		incompleteHistoryTask.launchBootstrap = {
			version: 1,
			records: [
				{
					...incompleteIdentity,
					identitySha256: createHash("sha256")
						.update(canonicalLaunchBootstrapBytes(incompleteIdentity))
						.digest("hex"),
				},
			],
		};
		assert.throws(
			() => recordLaunchBootstrapProvenance(incompleteHistoryTask, first),
			/launch-bootstrap provenance is malformed/,
		);
		const foreignHistoryTask = structuredClone(orderOnly.task);
		const foreign = structuredClone(first);
		foreign.runId = "foreign-run";
		foreign.attempt.launchRetry = 1;
		foreign.attempt.key =
			"launch-retry:1;output-retry:0;resume:0;session:none";
		const { identitySha256: _foreignIdentity, ...foreignBody } = foreign;
		foreign.identitySha256 = createHash("sha256")
			.update(canonicalLaunchBootstrapBytes(foreignBody))
			.digest("hex");
		foreignHistoryTask.launchBootstrap = { version: 1, records: [foreign] };
		assert.throws(
			() => recordLaunchBootstrapProvenance(foreignHistoryTask, first),
			/launch-bootstrap provenance is malformed/,
		);
		fixture.task.status = "failed";
		assert.equal(resetTaskForResume(fixture.task), true);
		assert.equal(fixture.task.launchBootstrap.records.length, 1);

		const divergence = async (mutate) => {
			const candidate = structuredClone(fixture);
			mutate(candidate);
			return await createLaunchBootstrapProvenance(
				cwd,
				candidate.run,
				candidate.task,
				candidate.compiledTask,
				"pi-subagent/headless",
			);
		};
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ compiledTask }) => {
					compiledTask.compiledPrompt = "different prompt";
				})
			).identitySha256,
		);
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ compiledTask }) => {
					compiledTask.contextDependsOn = ["explicit-source"];
				})
			).identitySha256,
		);
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ compiledTask }) => {
					compiledTask.runtime.tools = ["read", "grep"];
				})
			).identitySha256,
		);
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ compiledTask }) => {
					compiledTask.runtime.thinking = "high";
				})
			).identitySha256,
		);
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ task }) => {
					task.worktree.enabled = true;
					task.worktree.path = "/isolated-worktree";
				})
			).identitySha256,
		);
		await assert.rejects(
			divergence(({ task, compiledTask }) => {
				task.artifactGraph = {
					enabled: true,
					output: { analysisRequired: true, refsRequired: true },
					requiredReads: [],
					artifactAccess: "enabled",
				};
				compiledTask.artifactGraph = structuredClone(task.artifactGraph);
			}),
			(error) =>
				error instanceof Error &&
				/artifact manifest is unavailable/.test(error.message),
		);
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ task }) => {
					task.launchRetry = { attempts: 1 };
				})
			).identitySha256,
		);
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ task }) => {
					task.outputRetry = { attempts: 1, sessionId: "rotated-session" };
				})
			).identitySha256,
		);
		assert.notEqual(
			first.identitySha256,
			(
				await divergence(({ task }) => {
					task.resumeEvents = [{}];
				})
			).identitySha256,
		);

		const mismatchedTask = structuredClone(fixture.task);
		mismatchedTask.resumeEvents = [];
		const mismatchedCompiledTask = structuredClone(fixture.compiledTask);
		mismatchedCompiledTask.compiledPrompt = "different prompt";
		const mismatched = await createLaunchBootstrapProvenance(
			cwd,
			fixture.run,
			mismatchedTask,
			mismatchedCompiledTask,
			"pi-subagent/headless",
		);
		assert.throws(
			() => recordLaunchBootstrapProvenance(fixture.task, mismatched),
			(error) =>
				error instanceof Error &&
				/launch-bootstrap provenance mismatch/.test(error.message) &&
				!/Launch prompt|different prompt/.test(error.message),
		);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("launch-bootstrap provenance persists before launch and rejects same-attempt divergence", async () => {
	const cwd = makeProject();
	try {
		writeAgent(cwd, "unit-scout", "read");
		const spec = workflowSpec("unit-scout", {
			artifactGraph: {
				stages: [
					{
						id: "main",
						type: "single",
						prompt: "Produce valid workflow output.",
					},
				],
			},
		});
		const compiled = await compileWorkflow(spec, {
			cwd,
			task: "Bootstrap task",
		});
		const { run } = await createWorkflowRunRecord(
			cwd,
			compiled,
			join(cwd, "workflows", "bootstrap.json"),
		);
		await writeStaticRunArtifacts(cwd, run, compiled, spec);
		const prepared = await prepareDagTask(cwd, run, compiled, 0);
		const provenance = await createLaunchBootstrapProvenance(
			cwd,
			run,
			run.tasks[0],
			prepared,
			"pi-subagent/headless",
		);
		const forgedPrepared = structuredClone(prepared);
		forgedPrepared.compiledPrompt = "different prepared prompt";
		const forged = await createLaunchBootstrapProvenance(
			cwd,
			run,
			run.tasks[0],
			forgedPrepared,
			"pi-subagent/headless",
		);
		assert.notEqual(provenance.identitySha256, forged.identitySha256);
		run.tasks[0].launchBootstrap = { version: 1, records: [forged] };
		await writeRunRecord(cwd, run);

		let launches = 0;
		setSubagentApiForTests({
			async runSubagent() {
				launches += 1;
				return {
					runId: "unexpected",
					attemptId: "unexpected",
					status: "running",
				};
			},
			async getSubagentStatus() {
				return null;
			},
			async reconcileSubagentRun() {
				return {};
			},
			async interruptSubagent() {
				return {};
			},
		});
		try {
			await scheduleRun(cwd, run.runId, compiled);
			const reloaded = await readRunRecord(cwd, run.runId);
			assert.equal(launches, 0);
			assert.equal(reloaded.tasks[0].status, "failed");
			assert.equal(reloaded.tasks[0].statusDetail, "launch_failed");
			assert.match(
				reloaded.tasks[0].lastMessage,
				/launch-bootstrap provenance mismatch/,
			);
			assert.doesNotMatch(
				reloaded.tasks[0].lastMessage,
				/Produce valid workflow output|different prepared prompt/,
			);
		} finally {
			setSubagentApiForTests(undefined);
		}
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

